          </div>
          <button 
            onClick={() => setStudentTab('menu')}
            style={{ 
              background: 'none', 
              border: 'none', 
              color: 'var(--accent-blue)', 
              fontSize: '13px', 
              fontWeight: '700', 
              display: 'flex', 
              alignItems: 'center', 
              cursor: 'pointer' 
            }}
          >
            View Menu <ChevronRight size={14} />
          </button>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {specials.map((item) => (
            <div 
              key={item.id} 
              className="glass-card" 
              style={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                padding: '16px',
