                  width: '14px', height: '14px',
                  border: `2px solid ${item.veg ? '#10b981' : '#ef4444'}`,
                  borderRadius: '3px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: '1px',
                  flexShrink: 0
                }}>
                  <div style={{
                    width: '6px', height: '6px',
                    borderRadius: '50%',
                    backgroundColor: item.veg ? '#10b981' : '#ef4444'
                  }} />
