            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Search, Flame, ShoppingBag, Plus, Minus, Info } from 'lucide-react';

export default function Menu({ items, cart, addToCart, removeFromCart, activeOrders }) {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');
  const [vegOnly, setVegOnly] = useState(false);

  const categories = [
    { id: 'all', name: 'All Menu' },
    { id: 'breakfast', name: 'Breakfast' },
    { id: 'meals', name: 'Meals' },
    { id: 'snacks', name: 'Snacks' },
    { id: 'beverages', name: 'Drinks' }
  ];

  // Get item count in cart
  const getCartQuantity = (itemId) => {
    const cartItem = cart.find(c => c.item.id === itemId);
    return cartItem ? cartItem.quantity : 0;
  };

  // Filter items
  const filteredItems = items.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = activeCategory === 'all' || item.category === activeCategory;
    const matchesVeg = !vegOnly || item.veg;
    return matchesSearch && matchesCategory && matchesVeg;
  });

  return (
    <div className="portal-pane" style={{ animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
      {/* Search and Filters Header */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {/* Search Input */}
        <div style={{ position: 'relative', display: 'flex', width: '100%' }}>
          <Search size={18} color="var(--text-secondary)" style={{ position: 'absolute', left: '14px', top: '50%', transform: 'translateY(-50%)' }} />
          <input 
            type="text" 
            className="glass-input" 
            placeholder="Search hot samosas, crispy dosa..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ width: '100%', paddingLeft: '44px' }}
          />
        </div>

        {/* Veg/Non-Veg Toggle & Meta Info */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px' }}>
          <div style={{ display: 'flex', gap: '6px' }}>
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                className={`glass-btn ${activeCategory === cat.id ? 'glass-btn-primary' : ''}`}
                style={{ 
                  padding: '6px 14px', 
                  fontSize: '12px', 
                  borderRadius: '99px',
                  boxShadow: activeCategory === cat.id ? '0 4px 10px rgba(0,0,0,0.1)' : 'none'
                }}
              >
                {cat.name}
              </button>
            ))}
          </div>

          <label style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', cursor: 'pointer', fontSize: '13px', fontWeight: '600' }}>
            <input 
              type="checkbox" 
              checked={vegOnly}
              onChange={() => setVegOnly(!vegOnly)}
              style={{
                width: '16px', height: '16px',
                accentColor: 'var(--accent-green)',
                cursor: 'pointer'
              }}
            />
            🟢 Veg Only
          </label>
        </div>
      </div>

      {/* Menu Grid */}
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', 
        gap: '16px',
        maxHeight: 'calc(100vh - 290px)',
        overflowY: 'auto',
        paddingRight: '4px',
        paddingBottom: '20px'
      }}>
        {filteredItems.length > 0 ? (
          filteredItems.map((item) => {
            const qty = getCartQuantity(item.id);
            return (
              <div 
                key={item.id} 
                className="glass-card" 
                style={{ 
                  display: 'flex', 
                  flexDirection: 'column', 
                  justifyContent: 'space-between', 
