                  <div>
                    <span style={{ fontSize: '18px', fontWeight: '800', color: 'var(--text-primary)' }}>₹{item.price}</span>
                    <span style={{ display: 'block', fontSize: '10px', color: 'var(--text-tertiary)' }}>~{item.prepTime}m cook time</span>
                  </div>

                  {item.inStock ? (
                    qty > 0 ? (
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', background: 'var(--accent-primary)', borderRadius: 'var(--radius-xs)', padding: '4px' }}>
                        <button 
                          onClick={(e) => { e.stopPropagation(); removeFromCart(item.id); }}
                          style={{ background: 'none', border: 'none', color: 'var(--text-white)', cursor: 'pointer', padding: '4px' }}
                        >
                          <Minus size={14} />
                        </button>
                        <span style={{ color: 'var(--text-white)', fontWeight: '700', fontSize: '13px', minWidth: '16px', textAlign: 'center' }}>{qty}</span>
                        <button 
                          onClick={(e) => { e.stopPropagation(); addToCart(item); }}
                          style={{ background: 'none', border: 'none', color: 'var(--text-white)', cursor: 'pointer', padding: '4px' }}
                        >
                          <Plus size={14} />
                        </button>
                      </div>
                    ) : (
                      <button 
                        className="glass-btn glass-btn-primary" 
                        style={{ padding: '8px 16px', fontSize: '12px' }}
                        onClick={(e) => { e.stopPropagation(); addToCart(item); }}
                      >
                        Add to Cart
                      </button>
                    )
                  ) : (
                    <button 
                      className="glass-btn glass-btn-disabled" 
                      style={{ padding: '8px 16px', fontSize: '12px', backgroundColor: 'var(--text-tertiary)', border: 'none', color: 'var(--text-white)' }}
                      disabled
                    >
                      Unavailable
                    </button>
                  )}
                </div>
              </div>
            );
          })
        ) : (
          <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '40px 20px', color: 'var(--text-secondary)' }}>
            <p style={{ fontWeight: '600' }}>No items match your search/filters.</p>
            <span style={{ fontSize: '12px' }}>Try switching categories or disabling "Veg Only"</span>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { ShoppingBag, Clock, CreditCard, ShieldCheck, HelpCircle, Wallet, AlertTriangle, AlertCircle } from 'lucide-react';

export default function CartCheckout({ cart, walletBalance, checkout, setStudentTab, topUpWallet }) {
  const [isScheduled, setIsScheduled] = useState(false);
  const [scheduledSlot, setScheduledSlot] = useState('01:15 PM (Lunch Break)');
  const [paymentMethod, setPaymentMethod] = useState('wallet');
  const [checkoutStep, setCheckoutStep] = useState('cart'); // 'cart' -> 'simulating' -> 'success' | 'failure'
  const [note, setNote] = useState('');

  const slots = [
    '09:45 AM (Short Break)',
    '11:30 AM (Mid Break)',
    '01:15 PM (Lunch Break)',
    '03:30 PM (Tea Break)',
    '07:30 PM (Dinner Break)'
  ];

  const subtotal = cart.reduce((acc, curr) => acc + (curr.item.price * curr.quantity), 0);
  const packagingFee = subtotal > 0 ? 5 : 0;
  const gst = Math.round(subtotal * 0.05); // 5% GST
  const total = subtotal + packagingFee + gst;

  const handlePlaceOrder = () => {
    if (cart.length === 0) return;

    if (paymentMethod === 'wallet') {
      if (walletBalance < total) {
        setCheckoutStep('wallet_low');
        return;
      }
      setCheckoutStep('simulating');
      setTimeout(() => {
        // Successful wallet checkout
        const orderId = `TXN-${Math.floor(100000 + Math.random() * 900000)}`;
        const token = Math.floor(100 + Math.random() * 899);
        checkout({
          id: orderId,
          token: token,
          items: [...cart],
          total: total,
          paymentMethod: 'wallet',
          isScheduled: isScheduled,
          scheduledTime: isScheduled ? scheduledSlot : '',
          checkedIn: !isScheduled, // if instant, prep starts now, so checked-in is true
          note: note,
          status: 'received',
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }, total); // deduct wallet balance
        setCheckoutStep('success');
      }, 1200);
    } else {
      // Simulate UPI payment
      setCheckoutStep('simulating');
      setTimeout(() => {
        // High likelihood of network timeout at peak rush
        setCheckoutStep('upi_timeout');
      }, 2000);
    }
  };

  const handleBypassUpiFailure = () => {
    // Top up wallet with necessary amount and proceed via wallet
    const deficit = total - walletBalance;
    if (deficit > 0) {
      topUpWallet(deficit);
    }
    setPaymentMethod('wallet');
    setCheckoutStep('cart');
  };

  if (cart.length === 0 && checkoutStep === 'cart') {
    return (
      <div className="portal-pane" style={{ textAlign: 'center', padding: '40px 20px', animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
        <div style={{
          width: '60px', height: '60px', borderRadius: '50%',
          backgroundColor: 'rgba(15, 23, 42, 0.03)',
          display: 'flex', alignItems: 'center', justifyCenter: 'center',
          margin: '0 auto 16px', color: 'var(--text-secondary)'
        }}>
          <ShoppingBag size={28} style={{ margin: 'auto' }} />
        </div>
        <h3 style={{ fontSize: '18px', fontWeight: '800' }}>Your Cart is Empty</h3>
        <p style={{ fontSize: '13px', color: 'var(--text-secondary)', margin: '6px 0 20px' }}>
          Explore the menu to add hot snacks and meal boxes!
        </p>
        <button className="glass-btn glass-btn-primary" onClick={() => setStudentTab('menu')}>
          Browse Menu
        </button>
      </div>
    );
  }

  return (
    <div className="portal-pane" style={{ animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
      {checkoutStep === 'cart' && (
        <>
          {/* Order Summary Panel */}
          <div className="glass-panel" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '14px' }}>
            <h3 style={{ fontSize: '16px', fontWeight: '800', borderBottom: '1px solid rgba(15, 23, 42, 0.05)', paddingBottom: '10px' }}>
              Selected Items
            </h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '180px', overflowY: 'auto' }}>
              {cart.map((item) => (
                <div key={item.item.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '14px' }}>
                  <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                    <span style={{ fontWeight: '700', color: 'var(--text-secondary)' }}>{item.quantity}x</span>
                    <span style={{ fontWeight: '600' }}>{item.item.name}</span>
                  </div>
                  <span style={{ fontWeight: '700' }}>₹{item.item.price * item.quantity}</span>
                </div>
              ))}
            </div>

            <textarea 
              className="glass-input"
              placeholder="Any instructions? (e.g. less spicy, extra spoons)"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              style={{ fontSize: '13px', padding: '10px', height: '60px', resize: 'none', borderStyle: 'dashed' }}
            />
          </div>

          {/* Timing / Scheduling Panel */}
          <div className="glass-panel" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <Clock size={18} color="var(--accent-blue)" />
                <h3 style={{ fontSize: '15px', fontWeight: '800' }}>Order Timing</h3>
              </div>

              <div style={{ display: 'flex', background: 'rgba(15,23,42,0.05)', borderRadius: '99px', padding: '3px' }}>
                <button 
                  onClick={() => setIsScheduled(false)} 
                  className={`glass-btn ${!isScheduled ? 'glass-btn-primary' : ''}`}
                  style={{ padding: '4px 12px', fontSize: '11px', borderRadius: '99px', border: 'none', boxShadow: !isScheduled ? '0 2px 6px rgba(0,0,0,0.15)' : 'none' }}
                >
                  Instant
                </button>
                <button 
                  onClick={() => setIsScheduled(true)} 
                  className={`glass-btn ${isScheduled ? 'glass-btn-primary' : ''}`}
                  style={{ padding: '4px 12px', fontSize: '11px', borderRadius: '99px', border: 'none', boxShadow: isScheduled ? '0 2px 6px rgba(0,0,0,0.15)' : 'none' }}
                >
                  Schedule
                </button>
              </div>
            </div>

            {isScheduled ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }} style={{ animation: 'slideUp 0.3s ease-out' }}>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                  <label style={{ fontSize: '12px', color: 'var(--text-secondary)', fontWeight: '600' }}>Select Break Time Slot</label>
                  <select 
                    className="glass-input" 
                    value={scheduledSlot}
                    onChange={(e) => setScheduledSlot(e.target.value)}
                    style={{ width: '100%', cursor: 'pointer', fontWeight: '600' }}
                  >
                    {slots.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
                <div style={{ 
                  display: 'flex', gap: '8px', 
                  backgroundColor: 'var(--accent-blue-bg)', 
                  border: '1px solid rgba(2,132,199,0.15)',
                  padding: '10px 12px', borderRadius: 'var(--radius-sm)',
                  fontSize: '12px', color: 'var(--text-primary)', fontWeight: '500'
                }}>
                  <Info size={16} color="var(--accent-blue)" style={{ flexShrink: 0 }} />
                  <span><strong>Smart Pickup:</strong> Food won't sit cold! Prep starts only when you scan the check-in QR code or tap "Check-In" on arrival.</span>
                </div>
              </div>
            ) : (
              <p style={{ fontSize: '13px', color: 'var(--text-secondary)', fontWeight: '500' }}>
                Preparation starts immediately. Cook time estimate: <strong>10 mins</strong>.
              </p>
            )}
          </div>

          {/* Payment Method Panel */}
          <div className="glass-panel" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <CreditCard size={18} />
              <h3 style={{ fontSize: '15px', fontWeight: '800' }}>Payment Mode</h3>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <div 
                onClick={() => setPaymentMethod('wallet')}
                style={{
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  padding: '12px 14px', borderRadius: 'var(--radius-sm)',
                  border: `2px solid ${paymentMethod === 'wallet' ? 'var(--accent-primary)' : 'rgba(15,23,42,0.06)'}`,
                  background: paymentMethod === 'wallet' ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)',
                  cursor: 'pointer', transition: 'var(--transition-smooth)'
                }}
              >
                <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                  <Wallet size={18} color="var(--text-primary)" />
                  <div>
                    <span style={{ fontSize: '14px', fontWeight: '700', display: 'block' }}>Canteen Wallet</span>
                    <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Balance: ₹{walletBalance.toFixed(2)}</span>
                  </div>
                </div>
                <div style={{
                  width: '18px', height: '18px', borderRadius: '50%',
                  border: '2px solid var(--accent-primary)',
                  display: 'flex', alignItems: 'center', justifyCenter: 'center',
                  padding: '3px'
                }}>
                  {paymentMethod === 'wallet' && <div style={{ width: '100%', height: '100%', borderRadius: '50%', backgroundColor: 'var(--accent-primary)' }} />}
                </div>
              </div>

              <div 
                onClick={() => setPaymentMethod('upi')}
                style={{
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  padding: '12px 14px', borderRadius: 'var(--radius-sm)',
                  border: `2px solid ${paymentMethod === 'upi' ? 'var(--accent-primary)' : 'rgba(15,23,42,0.06)'}`,
                  background: paymentMethod === 'upi' ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.3)',
                  cursor: 'pointer', transition: 'var(--transition-smooth)'
                }}
              >
                <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                  <span style={{ fontSize: '18px', fontWeight: '900', fontStyle: 'italic', letterSpacing: '-1.5px', color: '#0284c7' }}>UPI</span>
                  <div>
                    <span style={{ fontSize: '14px', fontWeight: '700', display: 'block' }}>Direct UPI Gateway</span>
                    <span style={{ fontSize: '11px', color: 'var(--accent-orange)', fontWeight: '600' }}>⚠️ Peak Hour Network Failure Risk</span>
                  </div>
                </div>
                <div style={{
                  width: '18px', height: '18px', borderRadius: '50%',
                  border: '2px solid var(--accent-primary)',
                  display: 'flex', alignItems: 'center', justifyCenter: 'center',
                  padding: '3px'
                }}>
                  {paymentMethod === 'upi' && <div style={{ width: '100%', height: '100%', borderRadius: '50%', backgroundColor: 'var(--accent-primary)' }} />}
                </div>
              </div>
            </div>

            {/* Bill Summary */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', fontSize: '13px', borderTop: '1px solid rgba(15,23,42,0.05)', paddingTop: '12px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: 'var(--text-secondary)' }}>Subtotal</span>
                <span>₹{subtotal}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: 'var(--text-secondary)' }}>Packaging Fee</span>
                <span>₹{packagingFee}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: 'var(--text-secondary)' }}>CGST/SGST (5%)</span>
                <span>₹{gst}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '15px', fontWeight: '800', borderTop: '1px dotted rgba(15,23,42,0.1)', paddingTop: '8px', marginTop: '4px' }}>
                <span>Grand Total</span>
                <span>₹{total}</span>
              </div>
            </div>

            <button 
              className="glass-btn glass-btn-primary" 
              style={{ width: '100%', padding: '14px', borderRadius: 'var(--radius-sm)', fontSize: '15px' }}
              onClick={handlePlaceOrder}
            >
              Pay & Place Order (₹{total})
            </button>
          </div>
        </>
      )}

      {/* Simulator / Processing State */}
      {checkoutStep === 'simulating' && (
        <div className="glass-panel" style={{ padding: '40px 20px', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '20px' }}>
          <div style={{
            width: '60px', height: '60px',
            border: '4px solid rgba(15,23,42,0.08)',
            borderTopColor: 'var(--accent-primary)',
            borderRadius: '50%',
            animation: 'shimmer 1.5s infinite linear',
            borderRadius: '50%',
            boxSizing: 'border-box'
          }} className="pulse-animation" />
          <div>
            <h3 style={{ fontSize: '18px', fontWeight: '800' }}>Processing Payment...</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginTop: '6px' }}>
              {paymentMethod === 'wallet' ? 'Securing funds from wallet locally...' : 'Re-routing to UPI payment servers (Bank gateway)...'}
            </p>
          </div>
        </div>
      )}

      {/* Wallet Balance Deficit Warning */}
      {checkoutStep === 'wallet_low' && (
        <div className="glass-panel" style={{ padding: '32px 24px', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px' }}>
          <AlertCircle size={44} color="var(--accent-red)" />
          <div>
            <h3 style={{ fontSize: '18px', fontWeight: '800' }}>Insufficient Wallet Balance</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginTop: '6px' }}>
              Your current balance is <strong>₹{walletBalance.toFixed(2)}</strong>, but the total bill is <strong>₹{total}</strong>.
            </p>
          </div>

          <div style={{ display: 'flex', gap: '12px', width: '100%', marginTop: '8px' }}>
            <button className="glass-btn" style={{ flex: 1 }} onClick={() => setCheckoutStep('cart')}>
              Change Payment
            </button>
            <button 
              className="glass-btn glass-btn-primary" 
              style={{ flex: 1 }}
              onClick={() => {
                topUpWallet(total - walletBalance);
                setCheckoutStep('cart');
              }}
            >
              Recharge ₹{(total - walletBalance).toFixed(0)}
            </button>
          </div>
        </div>
      )}

      {/* UPI Network Failure Simulator */}
      {checkoutStep === 'upi_timeout' && (
        <div className="glass-panel" style={{ padding: '32px 24px', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px', border: '1px solid rgba(239, 68, 68, 0.4)' }}>
          <AlertTriangle size={48} color="var(--accent-orange)" className="pulse-animation" />
          <div>
            <h3 style={{ fontSize: '18px', fontWeight: '800', color: 'var(--text-primary)' }}>UPI Gateway Timed Out</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginTop: '8px', lineHeight: '1.4' }}>
              Canteen peak hour cell congestion occurred! The bank gateway timed out, causing payment failure.
            </p>
          </div>

          <div style={{ 
            backgroundColor: 'var(--accent-green-bg)', 
            border: '1px solid rgba(16,185,129,0.15)',
            padding: '12px', borderRadius: 'var(--radius-sm)',
            fontSize: '12px', color: 'var(--text-primary)', width: '100%',
            fontWeight: '600'
          }}>
            🎉 Bypass Trick: Recharge and pay with Canteen Wallet instantly using strong hostel WiFi or cellular network beforehand.
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', width: '100%' }}>
            <button 
              className="glass-btn glass-btn-primary" 
              style={{ width: '100%', background: 'var(--accent-green)', borderColor: 'var(--accent-green)' }}
              onClick={handleBypassUpiFailure}
            >
              Convert to Wallet Payment & Retry
            </button>
            <button className="glass-btn glass-btn-secondary" onClick={() => setCheckoutStep('cart')}>
              Back to Checkout
            </button>
          </div>
        </div>
      )}

      {/* Success View */}
      {checkoutStep === 'success' && (
        <div className="glass-panel" style={{ padding: '40px 20px', textAlign: 'center', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '20px' }}>
          <div style={{
            width: '60px', height: '60px', borderRadius: '50%',
            backgroundColor: 'var(--accent-green-bg)',
            display: 'flex', alignItems: 'center', justifyCenter: 'center',
            color: 'var(--accent-green)', margin: '0 auto'
          }}>
            <ShieldCheck size={36} style={{ margin: 'auto' }} />
          </div>
          <div>
            <h3 style={{ fontSize: '20px', fontWeight: '800' }}>Order Placed Successfully!</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginTop: '6px' }}>
              Your token has been sent to the kitchen. Track your order in the next tab.
            </p>
          </div>
          <button className="glass-btn glass-btn-primary" onClick={() => setStudentTab('tracker')}>
            Track Order
          </button>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Clock, CheckCircle2, ChevronRight, AlertCircle, QrCode, MapPin, ShieldAlert, Check } from 'lucide-react';

export default function OrderTracker({ activeOrders, triggerCheckIn }) {
  const [showQrToken, setShowQrToken] = useState(null); // stores order ID to show QR for

  if (activeOrders.length === 0) {
    return (
      <div className="portal-pane" style={{ textAlign: 'center', padding: '40px 20px', animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
        <div style={{
          width: '60px', height: '60px', borderRadius: '50%',
          backgroundColor: 'rgba(15, 23, 42, 0.03)',
          display: 'flex', alignItems: 'center', justifyCenter: 'center',
          margin: '0 auto 16px', color: 'var(--text-secondary)'
        }}>
          <Clock size={28} style={{ margin: 'auto' }} />
        </div>
        <h3 style={{ fontSize: '18px', fontWeight: '800' }}>No Active Orders</h3>
        <p style={{ fontSize: '13px', color: 'var(--text-secondary)', margin: '6px 0' }}>
          You don't have any orders cooking or scheduled right now.
        </p>
      </div>
    );
  }

  const getStatusStep = (status) => {
    switch(status) {
      case 'received': return 1;
      case 'preparing': return 2;
      case 'ready': return 3;
      case 'collected': return 4;
      default: return 1;
    }
  };

  return (
    <div className="portal-pane" style={{ animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)', maxHeight: 'calc(100vh - 200px)', overflowY: 'auto', paddingRight: '4px' }}>
      <h3 style={{ fontSize: '16px', fontWeight: '800', marginBottom: '4px' }}>Your Active Tokens</h3>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        {activeOrders.map((order) => {
          const currentStep = getStatusStep(order.status);

          return (
            <div key={order.id} className="glass-panel" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '16px', position: 'relative' }}>

              {/* Order Card Header */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <div>
                  <span style={{ fontSize: '12px', color: 'var(--text-secondary)', fontWeight: '700' }}>
                    Token #{order.token} • {order.timestamp}
                  </span>
                  <h4 style={{ fontSize: '18px', fontWeight: '900', letterSpacing: '-0.3px', marginTop: '2px' }}>
                    ₹{order.total} • {order.items.length} {order.items.length === 1 ? 'item' : 'items'}
                  </h4>
                </div>

                <button 
                  className="glass-btn" 
                  style={{ padding: '8px 12px', fontSize: '11px', display: 'flex', gap: '6px', alignItems: 'center' }}
                  onClick={() => setShowQrToken(showQrToken === order.id ? null : order.id)}
                >
                  <QrCode size={14} /> Get Token
                </button>
              </div>

              {/* Items Summary list */}
              <div style={{ fontSize: '13px', color: 'var(--text-secondary)', background: 'rgba(15,23,42,0.02)', padding: '10px 14px', borderRadius: 'var(--radius-xs)' }}>
                {order.items.map((i, idx) => (
                  <span key={idx} style={{ fontWeight: '600' }}>
                    {i.quantity}x {i.item.name}{idx < order.items.length - 1 ? ', ' : ''}
                  </span>
                ))}
                {order.note && <p style={{ fontSize: '11px', fontStyle: 'italic', color: 'var(--accent-orange)', marginTop: '4px' }}>Note: {order.note}</p>}
              </div>

              {/* Scheduled Order Flow (Awaiting check-in) */}
              {order.isScheduled && !order.checkedIn ? (
                <div style={{ 
                  display: 'flex', flexDirection: 'column', gap: '12px',
                  backgroundColor: 'var(--accent-orange-bg)', border: '1px solid rgba(249,115,22,0.15)',
                  padding: '16px', borderRadius: 'var(--radius-sm)'
                }}>
                  <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                    <MapPin size={20} color="var(--accent-orange)" style={{ flexShrink: 0, marginTop: '2px' }} />
                    <div style={{ textAlign: 'left' }}>
