                    }}>
                      <div style={{
                        height: '100%',
                        width: `${((currentStep - 1) / 3) * 100}%`,
                        backgroundColor: order.status === 'ready' || order.status === 'collected' ? 'var(--accent-green)' : 'var(--accent-blue)',
                        transition: 'var(--transition-smooth)'
                      }} />
                    </div>

                    {/* Timeline Nodes */}
                    {[
                      { step: 1, label: 'Placed' },
                      { step: 2, label: 'Kitchen' },
                      { step: 3, label: 'Ready' },
                      { step: 4, label: 'Collected' }
                    ].map((node) => {
                      const isActive = currentStep >= node.step;
                      const isCompleted = currentStep > node.step;
                      let nodeBg = 'var(--text-white)';
                      let nodeBorderColor = 'rgba(15,23,42,0.08)';
                      let iconColor = 'var(--text-tertiary)';

                      if (isActive) {
                        nodeBorderColor = order.status === 'ready' || order.status === 'collected' ? 'var(--accent-green)' : 'var(--accent-blue)';
                        nodeBg = nodeBorderColor;
                        iconColor = 'var(--text-white)';
                      }

                      return (
                        <div key={node.step} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px', zIndex: 2, position: 'relative' }}>
                          <div style={{
                            width: '26px', height: '26px', borderRadius: '50%',
