function App() {
  const [viewMode, setViewMode] = useState('split'); // 'split' | 'student' | 'staff'
  const [studentTab, setStudentTab] = useState('dashboard'); // 'dashboard' | 'menu' | 'cart' | 'tracker'

  // App states
  const [items, setItems] = useState(INITIAL_ITEMS);
  const [cart, setCart] = useState([]);
  const [walletBalance, setWalletBalance] = useState(245.50);
  const [soundAnnouncer, setSoundAnnouncer] = useState(true);

  // Seed initial order for demonstration visual
  const [orders, setOrders] = useState([
    {
      id: "TXN-847291",
      token: 124,
      items: [
        { item: INITIAL_ITEMS[5], quantity: 2 }, // Samosa
        { item: INITIAL_ITEMS[7], quantity: 1 }  // Chai
      ],
      total: 35,
      status: "preparing",
      paymentMethod: "wallet",
      isScheduled: false,
      scheduledTime: "",
      checkedIn: true,
      note: "Keep the chai boiling hot!",
      timestamp: "07:42 PM"
    }
  ]);

  // Handle responsive view shifting automatically
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth <= 1024 && viewMode === 'split') {
        setViewMode('student');
      }
    };
    window.addEventListener('resize', handleResize);
    handleResize(); // trigger once on mount
    return () => window.removeEventListener('resize', handleResize);
  }, [viewMode]);

  // Speech Synthesizer Soundbox announcer
  const announceText = (text) => {
    if ('speechSynthesis' in window && soundAnnouncer) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.rate = 0.95;
      utterance.pitch = 1.0;

      const voices = window.speechSynthesis.getVoices();
      const preferred = voices.find(v => v.lang.includes('en-IN') || v.lang.includes('hi-IN'));
      if (preferred) utterance.voice = preferred;

      window.speechSynthesis.speak(utterance);
    }
  };

  // Add item to cart
  const addToCart = (item) => {
    setCart(currentCart => {
      const existing = currentCart.find(c => c.item.id === item.id);
      if (existing) {
        return currentCart.map(c => c.item.id === item.id ? { ...c, quantity: c.quantity + 1 } : c);
      }
      return [...currentCart, { item, quantity: 1 }];
    });
  };

  // Remove item from cart
  const removeFromCart = (itemId) => {
    setCart(currentCart => {
      const existing = currentCart.find(c => c.item.id === itemId);
      if (existing.quantity === 1) {
        return currentCart.filter(c => c.item.id !== itemId);
      }
      return currentCart.map(c => c.item.id === itemId ? { ...c, quantity: c.quantity - 1 } : c);
    });
  };

  // Wallet top up
  const topUpWallet = (amount) => {
    setWalletBalance(b => b + amount);
    announceText(`Recharge of rupees ${amount.toFixed(0)} received in your canteen wallet.`);
  };

  // Checkout cart
  const checkout = (newOrder, totalBill) => {
    setOrders(current => [newOrder, ...current]);
    setCart([]); // Clear cart
    setWalletBalance(b => b - totalBill); // Deduct wallet

    // Voice announcements depending on scheduled or instant
    if (newOrder.isScheduled) {
      announceText(`Token number ${newOrder.token} scheduled successfully. Please check-in when you arrive.`);
    } else {
      announceText(`New order received! Token number ${newOrder.token}.`);
    }
  };

  // Update order status (Staff side)
  const updateOrderStatus = (orderId, newStatus) => {
    setOrders(currentOrders => 
      currentOrders.map(order => {
        if (order.id === orderId) {
          const updated = { ...order, status: newStatus };

          // trigger voice announcer depending on status update
          if (newStatus === 'preparing') {
            announceText(`Token number ${order.token} is now preparing in kitchen.`);
          } else if (newStatus === 'ready') {
            announceText(`Pay attention! Token number ${order.token} is ready for collection!`);
          } else if (newStatus === 'collected') {
            announceText(`Thank you. Token number ${order.token} picked up.`);
          }

          return updated;
        }
        return order;
      })
    );
  };

  // Toggle inventory item stock
  const toggleStock = (itemId) => {
    setItems(currentItems =>
      currentItems.map(item => item.id === itemId ? { ...item, inStock: !item.inStock } : item)
    );
  };

  // Trigger check-in on scheduled orders
  const triggerCheckIn = (orderId) => {
    setOrders(currentOrders =>
      currentOrders.map(order => {
        if (order.id === orderId) {
          announceText(`Token ${order.token} checked in! Chef has started cooking.`);
          return { ...order, checkedIn: true, status: 'received' };
        }
        return order;
      })
    );
  };

  const activeOrdersCount = orders.filter(o => o.status !== 'collected').length;
  const cartCount = cart.reduce((acc, curr) => acc + curr.quantity, 0);

  return (
    <div className="app-container">
      {/* Universal Liquid Header */}
      <header className="glass-panel app-header">
        <div className="logo-section">
          <div className="logo-icon">
            <ShoppingBag size={22} strokeWidth={2.5} />
          </div>
          <div>
            <h1 className="logo-title">GlassCanteen</h1>
            <p className="logo-subtitle">Liquid Glass Ecosystem</p>
          </div>
        </div>

        {/* View Mode Switcher (Desktop Presentation Only) */}
        <div className="view-selector">
          <button 
            className={`selector-btn ${viewMode === 'split' ? 'active' : ''}`}
            onClick={() => setViewMode('split')}
            style={{ display: window.innerWidth > 1024 ? 'flex' : 'none' }}
          >
            <Laptop size={15} /> Split Screen
          </button>
          <button 
            className={`selector-btn ${viewMode === 'student' ? 'active' : ''}`}
            onClick={() => setViewMode('student')}
          >
            🧑‍🎓 Student Portal
          </button>
          <button 
            className={`selector-btn ${viewMode === 'staff' ? 'active' : ''}`}
            onClick={() => setViewMode('staff')}
          >
            🍳 Staff Console
          </button>
        </div>
      </header>

      {/* Main Content Workspace */}
      <main style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>

        {viewMode === 'split' ? (
          /* Split Screen: Side by side Student and Staff Dashboard */
          <div className="split-view-container">
            {/* Student Portal (Left) */}
            <div className="portal-pane" style={{ borderRight: '1px solid rgba(15,23,42,0.05)', paddingRight: '14px' }}>
              <div className="pane-header">
                <h2 className="pane-title">🧑‍🎓 Student Portal</h2>
                <span className="pane-badge badge-student">Live client</span>
              </div>

              {/* Student Internal Nav */}
              <div className="nav-tabs">
                <div className={`nav-tab ${studentTab === 'dashboard' ? 'active' : ''}`} onClick={() => setStudentTab('dashboard')}>
                  Home
                </div>
                <div className={`nav-tab ${studentTab === 'menu' ? 'active' : ''}`} onClick={() => setStudentTab('menu')}>
                  Menu
                </div>
                <div className={`nav-tab ${studentTab === 'cart' ? 'active' : ''}`} onClick={() => setStudentTab('cart')}>
                  Cart {cartCount > 0 && <span style={{ background: 'var(--accent-primary)', color: 'white', borderRadius: '50%', padding: '2px 7px', fontSize: '10px', marginLeft: '4px' }}>{cartCount}</span>}
                </div>
                <div className={`nav-tab ${studentTab === 'tracker' ? 'active' : ''}`} onClick={() => setStudentTab('tracker')}>
                  Track {activeOrdersCount > 0 && <span style={{ background: 'var(--accent-blue)', color: 'white', borderRadius: '50%', padding: '2px 7px', fontSize: '10px', marginLeft: '4px' }}>{activeOrdersCount}</span>}
                </div>
              </div>

              {/* Student Portal Sub-views */}
              <div style={{ flex: 1 }}>
                {studentTab === 'dashboard' && (
                  <Dashboard 
                    items={items} 
                    walletBalance={walletBalance} 
                    topUpWallet={topUpWallet} 
                    activeOrders={orders} 
                    addToCart={addToCart}
                    setStudentTab={setStudentTab}
                  />
                )}
                {studentTab === 'menu' && (
                  <Menu 
                    items={items} 
                    cart={cart}
                    addToCart={addToCart} 
                    removeFromCart={removeFromCart} 
                    activeOrders={orders}
                  />
                )}
                {studentTab === 'cart' && (
                  <CartCheckout 
                    cart={cart} 
                    walletBalance={walletBalance} 
                    checkout={checkout} 
                    setStudentTab={setStudentTab}
                    topUpWallet={topUpWallet}
                  />
                )}
                {studentTab === 'tracker' && (
                  <OrderTracker 
                    activeOrders={orders.filter(o => o.status !== 'collected')} 
                    triggerCheckIn={triggerCheckIn}
                  />
                )}
              </div>
            </div>

            {/* Canteen Staff Console (Right) */}
            <div className="portal-pane" style={{ paddingLeft: '14px' }}>
              <div className="pane-header">
                <h2 className="pane-title">🍳 Canteen Kitchen Console</h2>
                <span className="pane-badge badge-staff">Fulfillment Node</span>
              </div>

              <StaffPortal 
                orders={orders} 
                items={items}
                updateOrderStatus={updateOrderStatus} 
                toggleStock={toggleStock}
                soundAnnouncer={soundAnnouncer}
                setSoundAnnouncer={setSoundAnnouncer}
              />
            </div>
          </div>
        ) : viewMode === 'student' ? (
          /* Student Portal View (Mobile-responsive size or isolated view) */
          <div className="portal-pane" style={{ maxWidth: '600px', margin: '0 auto', width: '100%' }}>
            <div className="nav-tabs">
              <div className={`nav-tab ${studentTab === 'dashboard' ? 'active' : ''}`} onClick={() => setStudentTab('dashboard')}>
                Home
              </div>
              <div className={`nav-tab ${studentTab === 'menu' ? 'active' : ''}`} onClick={() => setStudentTab('menu')}>
                Menu
              </div>
              <div className={`nav-tab ${studentTab === 'cart' ? 'active' : ''}`} onClick={() => setStudentTab('cart')}>
                Cart {cartCount > 0 && <span style={{ background: 'var(--accent-primary)', color: 'white', borderRadius: '50%', padding: '2px 7px', fontSize: '10px', marginLeft: '4px' }}>{cartCount}</span>}
              </div>
              <div className={`nav-tab ${studentTab === 'tracker' ? 'active' : ''}`} onClick={() => setStudentTab('tracker')}>
                Track {activeOrdersCount > 0 && <span style={{ background: 'var(--accent-blue)', color: 'white', borderRadius: '50%', padding: '2px 7px', fontSize: '10px', marginLeft: '4px' }}>{activeOrdersCount}</span>}
              </div>
            </div>

            <div style={{ flex: 1 }}>
              {studentTab === 'dashboard' && (
                <Dashboard 
                  items={items} 
                  walletBalance={walletBalance} 
                  topUpWallet={topUpWallet} 
                  activeOrders={orders} 
                  addToCart={addToCart}
                  setStudentTab={setStudentTab}
                />
              )}
              {studentTab === 'menu' && (
                <Menu 
                  items={items} 
                  cart={cart}
                  addToCart={addToCart} 
                  removeFromCart={removeFromCart} 
                  activeOrders={orders}
                />
              )}
              {studentTab === 'cart' && (
                <CartCheckout 
                  cart={cart} 
                  walletBalance={walletBalance} 
                  checkout={checkout} 
                  setStudentTab={setStudentTab}
                  topUpWallet={topUpWallet}
                />
              )}
              {studentTab === 'tracker' && (
                <OrderTracker 
                  activeOrders={orders.filter(o => o.status !== 'collected')} 
                  triggerCheckIn={triggerCheckIn}
                />
              )}
            </div>
          </div>
        ) : (
          /* Canteen Staff Console (Isolated full-width view) */
          <div className="portal-pane" style={{ maxWidth: '800px', margin: '0 auto', width: '100%' }}>
            <StaffPortal 
              orders={orders} 
              items={items}
              updateOrderStatus={updateOrderStatus} 
              toggleStock={toggleStock}
              soundAnnouncer={soundAnnouncer}
              setSoundAnnouncer={setSoundAnnouncer}
            />
          </div>
        )}
      </main>

      {/* Aesthetic Footer */}
      <footer style={{ 
        textAlign: 'center', 
        fontSize: '11px', 
        color: 'var(--text-tertiary)', 
        padding: '16px 0', 
        borderTop: '1px solid rgba(15,23,42,0.03)',
        display: 'flex', justifyContent: 'center', gap: '20px', alignItems: 'center'
      }}>
        <span>🔐 GlassCanteen Core System v1.2</span>
        <span>•</span>
        <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
          <ShieldCheck size={12} color="var(--accent-green)" /> Secured with CryptoCache Tokens
        </span>
      </footer>
    </div>
  );
}

export default App;

